class Solution {public:
 long long maxArea(vector<vector<int>>& coords){
  unordered_map<int,pair<int,int>> xs,ys;int minX=INT_MAX,maxX=INT_MIN,minY=INT_MAX,maxY=INT_MIN;
  for(auto&p:coords){int x=p[0],y=p[1];minX=min(minX,x);maxX=max(maxX,x);minY=min(minY,y);maxY=max(maxY,y);
   if(!xs.count(x))xs[x]={y,y};else{xs[x].first=min(xs[x].first,y);xs[x].second=max(xs[x].second,y);}
   if(!ys.count(y))ys[y]={x,x};else{ys[y].first=min(ys[y].first,x);ys[y].second=max(ys[y].second,x);}
  }
  long long ans=0;
  for(auto &p:xs)ans=max(ans,1LL*(p.second.second-p.second.first)*max(maxX-p.first,minX==INT_MAX?0:p.first-minX));
  for(auto &p:ys)ans=max(ans,1LL*(p.second.second-p.second.first)*max(maxY-p.first,p.first-minY));
  return ans?ans:-1;
 }
};
